(function () {
  "use strict";

  const STORAGE_KEY = "tendora.the-hand-remains.world.v1";
  const SCHEMA_VERSION = 1;
  const MAX_GESTURES = 5000;
  const MAX_RECEIPTS = 12000;
  const LAW_KINDS = new Set(["constraint", "invariant", "boundary"]);
  const VERDICTS = new Set(["holds", "unknown", "strains"]);

  const KINDS = {
    question: {
      label: "Question",
      glyph: "?",
      color: "#b85f42",
      placeholder: "What do you want to understand well enough to change?",
    },
    constraint: {
      label: "Constraint",
      glyph: "⌜",
      color: "#b08a3d",
      placeholder: "What pressure would give this possibility a useful shape?",
    },
    invariant: {
      label: "Invariant",
      glyph: "∞",
      color: "#52655b",
      placeholder: "What must remain true while everything else is allowed to change?",
    },
    boundary: {
      label: "Boundary",
      glyph: "⊘",
      color: "#71596e",
      placeholder: "What must this world refuse in order to protect what matters?",
    },
    rehearsal: {
      label: "Rehearsal",
      glyph: "△",
      color: "#557888",
      placeholder: "Which possible world should be tried before it becomes costly?",
    },
    witness: {
      label: "Witness",
      glyph: "•",
      color: "#74736a",
      placeholder: "What happened when intention met reality?",
    },
  };

  const elements = {};
  let state;
  let selectedKind = "question";
  let selectedId = null;
  let replyToId = null;
  let currentView = "material";
  let rehearsalSourceId = null;
  let toastTimer = null;
  let saveTimer = null;

  function byId(id) {
    return document.getElementById(id);
  }

  function uid(prefix) {
    if (window.crypto && typeof window.crypto.randomUUID === "function") {
      return `${prefix}-${window.crypto.randomUUID()}`;
    }
    return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  }

  function nowIso() {
    return new Date().toISOString();
  }

  function dayKey(date) {
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(date);
    const part = (type) => parts.find((item) => item.type === type)?.value || "00";
    return `${part("year")}-${part("month")}-${part("day")}`;
  }

  function checksum(value) {
    let hash = 2166136261;
    for (let index = 0; index < value.length; index += 1) {
      hash ^= value.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(16).padStart(8, "0");
  }

  function receiptPayload(receipt) {
    return {
      seq: receipt.seq,
      at: receipt.at,
      action: receipt.action,
      target: receipt.target,
      detail: receipt.detail,
      previous: receipt.previous,
    };
  }

  function appendReceiptTo(world, action, target, detail, at = nowIso()) {
    const previous = world.receipts.length
      ? world.receipts[world.receipts.length - 1].hash
      : "origin";
    const receipt = {
      seq: world.receipts.length + 1,
      at,
      action: String(action).slice(0, 80),
      target: String(target).slice(0, 120),
      detail: String(detail).slice(0, 700),
      previous,
    };
    receipt.hash = checksum(JSON.stringify(receiptPayload(receipt)));
    world.receipts.push(receipt);
    return receipt;
  }

  function appendReceipt(action, target, detail) {
    return appendReceiptTo(state, action, target, detail);
  }

  function createFreshWorld() {
    const base = Date.now() - 5 * 60 * 1000;
    const createdAt = new Date(base).toISOString();
    const ids = {
      invariant: uid("gesture"),
      boundary: uid("gesture"),
      question: uid("gesture"),
      constraint: uid("gesture"),
      witness: uid("gesture"),
    };
    const gestures = [
      {
        id: ids.invariant,
        kind: "invariant",
        text: "The artist must be able to recognize their intention in what grows.",
        responseTo: null,
        status: "alive",
        createdAt: new Date(base).toISOString(),
        meta: { inherited: true },
      },
      {
        id: ids.boundary,
        kind: "boundary",
        text: "No artifact may hide the trail by which intention became consequence.",
        responseTo: ids.invariant,
        status: "alive",
        createdAt: new Date(base + 60000).toISOString(),
        meta: { inherited: true },
      },
      {
        id: ids.question,
        kind: "question",
        text: "Can resistance become more specific without turning the workbench into an oracle?",
        responseTo: ids.invariant,
        status: "alive",
        createdAt: new Date(base + 120000).toISOString(),
        meta: { inherited: true },
      },
      {
        id: ids.constraint,
        kind: "constraint",
        text: "The world must work without a build, account, network, or AI dependency.",
        responseTo: ids.question,
        status: "alive",
        createdAt: new Date(base + 180000).toISOString(),
        meta: { inherited: true },
      },
      {
        id: ids.witness,
        kind: "witness",
        text: "The programmer did not miss typing. They missed touching the material.",
        responseTo: ids.question,
        status: "alive",
        createdAt: new Date(base + 240000).toISOString(),
        meta: { inherited: true },
      },
    ];

    const world = {
      schema: SCHEMA_VERSION,
      worldId: uid("world"),
      name: "The Hand Remains",
      createdAt,
      updatedAt: createdAt,
      nextMove: "Can resistance become more specific without turning the workbench into an oracle?",
      visits: [dayKey(new Date())],
      gestures,
      receipts: [],
    };

    appendReceiptTo(world, "begin world", world.worldId, "The inherited memory received a material form.", createdAt);
    gestures.forEach((gesture) => {
      appendReceiptTo(
        world,
        `inherit ${gesture.kind}`,
        gesture.id,
        gesture.text,
        gesture.createdAt
      );
    });
    return world;
  }

  function verifyReceiptChain(world) {
    if (!Array.isArray(world.receipts)) return false;
    let previous = "origin";
    for (let index = 0; index < world.receipts.length; index += 1) {
      const receipt = world.receipts[index];
      if (receipt.seq !== index + 1 || receipt.previous !== previous) return false;
      if (checksum(JSON.stringify(receiptPayload(receipt))) !== receipt.hash) return false;
      previous = receipt.hash;
    }
    return true;
  }

  function validDate(value) {
    return typeof value === "string" && !Number.isNaN(Date.parse(value));
  }

  function limitedString(value, max, fallback = "") {
    return typeof value === "string" ? value.slice(0, max) : fallback;
  }

  function sanitizeImportedWorld(candidate) {
    if (!candidate || typeof candidate !== "object") throw new Error("This file does not contain a world.");
    if (candidate.schema !== SCHEMA_VERSION) throw new Error("This world uses an unsupported schema.");
    if (!Array.isArray(candidate.gestures) || !Array.isArray(candidate.receipts)) {
      throw new Error("The material or receipt trail is missing.");
    }
    if (candidate.gestures.length > MAX_GESTURES || candidate.receipts.length > MAX_RECEIPTS) {
      throw new Error("This world is too large to inspect safely here.");
    }

    const ids = new Set();
    const gestures = candidate.gestures.map((gesture) => {
      if (!gesture || typeof gesture !== "object") throw new Error("A gesture is malformed.");
      const id = limitedString(gesture.id, 120);
      const text = limitedString(gesture.text, 600).trim();
      if (!id || ids.has(id) || !text || !KINDS[gesture.kind] || !validDate(gesture.createdAt)) {
        throw new Error("A gesture could not be verified.");
      }
      ids.add(id);
      const sourceMeta = gesture.meta && typeof gesture.meta === "object" ? gesture.meta : {};
      const assessments = Array.isArray(sourceMeta.assessments)
        ? sourceMeta.assessments.slice(0, 500).map((assessment) => {
            const lawId = limitedString(assessment?.lawId, 120);
            const verdict = limitedString(assessment?.verdict, 20);
            if (!lawId || !VERDICTS.has(verdict)) throw new Error("A rehearsal assessment is malformed.");
            return { lawId, verdict };
          })
        : undefined;
      const meta = {
        inherited: Boolean(sourceMeta.inherited),
      };
      if (assessments) meta.assessments = assessments;
      if (typeof sourceMeta.notes === "string") meta.notes = sourceMeta.notes.slice(0, 500);
      if (typeof sourceMeta.sourceId === "string") meta.sourceId = sourceMeta.sourceId.slice(0, 120);
      if (typeof sourceMeta.latestRehearsalId === "string") {
        meta.latestRehearsalId = sourceMeta.latestRehearsalId.slice(0, 120);
      }
      return {
        id,
        kind: gesture.kind,
        text,
        responseTo: typeof gesture.responseTo === "string" ? gesture.responseTo.slice(0, 120) : null,
        status: gesture.status === "settled" ? "settled" : "alive",
        createdAt: gesture.createdAt,
        meta,
      };
    });

    gestures.forEach((gesture) => {
      if (gesture.responseTo && !ids.has(gesture.responseTo)) gesture.responseTo = null;
      if (gesture.meta.sourceId && !ids.has(gesture.meta.sourceId)) delete gesture.meta.sourceId;
      if (gesture.meta.latestRehearsalId && !ids.has(gesture.meta.latestRehearsalId)) {
        delete gesture.meta.latestRehearsalId;
      }
      if (gesture.meta.assessments) {
        gesture.meta.assessments = gesture.meta.assessments.filter((item) => ids.has(item.lawId));
      }
    });

    const receipts = candidate.receipts.map((receipt, index) => {
      if (!receipt || typeof receipt !== "object" || !validDate(receipt.at)) {
        throw new Error("A receipt is malformed.");
      }
      return {
        seq: receipt.seq,
        at: receipt.at,
        action: limitedString(receipt.action, 80),
        target: limitedString(receipt.target, 120),
        detail: limitedString(receipt.detail, 700),
        previous: limitedString(receipt.previous, 16),
        hash: limitedString(receipt.hash, 16),
      };
    });

    const world = {
      schema: SCHEMA_VERSION,
      worldId: limitedString(candidate.worldId, 120) || uid("world"),
      name: limitedString(candidate.name, 120, "Carried Tendora World"),
      createdAt: validDate(candidate.createdAt) ? candidate.createdAt : nowIso(),
      updatedAt: validDate(candidate.updatedAt) ? candidate.updatedAt : nowIso(),
      nextMove: limitedString(candidate.nextMove, 280),
      visits: Array.isArray(candidate.visits)
        ? [...new Set(candidate.visits.filter((item) => typeof item === "string").slice(0, 400))]
        : [],
      gestures,
      receipts,
    };

    if (!verifyReceiptChain(world)) throw new Error("The receipt chain does not verify.");
    return world;
  }

  function loadState() {
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) return createFreshWorld();
      return sanitizeImportedWorld(JSON.parse(raw));
    } catch (error) {
      window.setTimeout(() => showToast(`A fresh surface was opened: ${error.message}`), 300);
      return createFreshWorld();
    }
  }

  function persist() {
    state.updatedAt = nowIso();
    elements.saveState.classList.add("is-saving");
    elements.saveState.querySelector("span:last-child").textContent = "Holding…";
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      window.clearTimeout(saveTimer);
      saveTimer = window.setTimeout(() => {
        elements.saveState.classList.remove("is-saving");
        elements.saveState.querySelector("span:last-child").textContent = "Held here";
      }, 260);
    } catch (error) {
      elements.saveState.classList.remove("is-saving");
      elements.saveState.querySelector("span:last-child").textContent = "In memory only";
      showToast("Browser storage is unavailable. Export to carry this world forward.");
    }
  }

  function noteVisit() {
    const today = dayKey(new Date());
    if (!state.visits.includes(today)) {
      state.visits.push(today);
      appendReceipt("return to world", state.worldId, `The hand returned on ${today}.`);
      persist();
    }
  }

  function cacheElements() {
    [
      "saveState", "kindPalette", "composer", "composerKindLabel", "composerText",
      "characterCount", "replyContext", "replyTarget", "clearReply", "handoff",
      "handoffTitle", "editHandoffButton", "visitCount", "materialCount", "receiptCount",
      "materialFilter", "materialView", "materialList", "emptyMaterial", "constellationView",
      "constellation", "constellationEdges", "constellationNodes", "constellationLegend",
      "receiptView", "receiptList", "chainState", "inspector", "inspectorIdle",
      "inspectorContent", "inspectorKind", "inspectorText", "inspectorTime", "closeInspector",
      "lineageSection", "lineageLink", "tensionSection", "tensionSummary", "inspectorReceipt",
      "threadButton", "rehearseButton", "settleButton", "handoffForm", "handoffInput",
      "exportButton", "importButton", "importFile", "newWorldButton", "rehearsalDialog",
      "rehearsalForm", "rehearsalSource", "lawAssessments", "rehearsalNotes",
      "newWorldDialog", "newWorldForm", "confirmPhrase", "confirmNewWorld", "toast",
    ].forEach((id) => {
      elements[id] = byId(id);
    });
    elements.viewTabs = [...document.querySelectorAll(".view-tab")];
    elements.kindButtons = [...document.querySelectorAll(".kind-button")];
  }

  function findGesture(id) {
    return state.gestures.find((gesture) => gesture.id === id) || null;
  }

  function lastReceiptFor(target) {
    for (let index = state.receipts.length - 1; index >= 0; index -= 1) {
      if (state.receipts[index].target === target) return state.receipts[index];
    }
    return null;
  }

  function formatDate(value, includeDate = true) {
    const options = includeDate
      ? { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit" }
      : { hour: "2-digit", minute: "2-digit" };
    return new Intl.DateTimeFormat(undefined, options).format(new Date(value));
  }

  function truncate(text, length) {
    return text.length > length ? `${text.slice(0, length - 1).trim()}…` : text;
  }

  function showToast(message) {
    if (!elements.toast) return;
    elements.toast.textContent = message;
    elements.toast.classList.add("is-visible");
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(() => elements.toast.classList.remove("is-visible"), 3200);
  }

  function latestRehearsalFor(gesture) {
    if (gesture.kind === "rehearsal" && Array.isArray(gesture.meta.assessments)) return gesture;
    if (gesture.meta.latestRehearsalId) return findGesture(gesture.meta.latestRehearsalId);
    for (let index = state.gestures.length - 1; index >= 0; index -= 1) {
      const candidate = state.gestures[index];
      if (candidate.kind === "rehearsal" && candidate.meta.sourceId === gesture.id) return candidate;
    }
    return null;
  }

  function tensionCount(gesture) {
    const rehearsal = latestRehearsalFor(gesture);
    return rehearsal?.meta.assessments?.filter((item) => item.verdict === "strains").length || 0;
  }

  function renderHeader() {
    elements.visitCount.textContent = String(state.visits.length).padStart(2, "0");
    elements.handoffTitle.textContent = state.nextMove || "No thread has been left. Choose what the next hand should meet.";
    elements.handoffInput.value = state.nextMove || "";
    elements.materialCount.textContent = state.gestures.length;
    elements.receiptCount.textContent = state.receipts.length;
  }

  function materialMatches(gesture, filter) {
    if (filter === "all") return true;
    if (filter === "laws") return LAW_KINDS.has(gesture.kind) && gesture.status === "alive";
    if (filter === "tensions") return tensionCount(gesture) > 0;
    return gesture.status === "alive";
  }

  function makeElement(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function renderMaterial() {
    const filter = elements.materialFilter.value;
    const material = state.gestures.filter((gesture) => materialMatches(gesture, filter)).reverse();
    elements.materialList.replaceChildren();
    elements.emptyMaterial.hidden = material.length !== 0;

    material.forEach((gesture) => {
      const index = state.gestures.findIndex((item) => item.id === gesture.id) + 1;
      const kind = KINDS[gesture.kind];
      const card = makeElement("article", "material-card");
      card.dataset.kind = gesture.kind;
      card.dataset.id = gesture.id;
      if (gesture.id === selectedId) card.classList.add("is-selected");
      if (gesture.status === "settled") card.classList.add("is-settled");

      card.appendChild(makeElement("span", "material-index", String(index).padStart(2, "0")));

      const main = makeElement("button", "material-main");
      main.type = "button";
      main.dataset.select = gesture.id;
      main.setAttribute("aria-label", `Inspect ${kind.label}: ${gesture.text}`);
      const type = makeElement("span", "material-type");
      type.appendChild(makeElement("span", "", kind.glyph));
      type.appendChild(makeElement("span", "", gesture.status === "settled" ? `${kind.label} · settled` : kind.label));
      main.appendChild(type);
      main.appendChild(makeElement("span", "material-text", gesture.text));
      if (gesture.responseTo) {
        const parent = findGesture(gesture.responseTo);
        if (parent) main.appendChild(makeElement("span", "material-lineage", `↳ ${truncate(parent.text, 90)}`));
      }
      card.appendChild(main);

      const meta = makeElement("div", "material-meta");
      const tensions = tensionCount(gesture);
      if (tensions) meta.appendChild(makeElement("span", "tension-mark", `${tensions} tension${tensions === 1 ? "" : "s"}`));
      meta.appendChild(makeElement("time", "", formatDate(gesture.createdAt, false)));
      card.appendChild(meta);
      elements.materialList.appendChild(card);
    });
  }

  function svgElement(name, attributes = {}) {
    const node = document.createElementNS("http://www.w3.org/2000/svg", name);
    Object.entries(attributes).forEach(([key, value]) => node.setAttribute(key, value));
    return node;
  }

  function renderConstellation() {
    elements.constellationEdges.replaceChildren();
    elements.constellationNodes.replaceChildren();
    elements.constellationLegend.replaceChildren();

    const visible = state.gestures.slice(-60);
    const visibleIds = new Set(visible.map((gesture) => gesture.id));
    const lanes = Object.keys(KINDS);
    const positions = new Map();
    const left = 58;
    const width = 784;
    const laneTop = 55;
    const laneGap = 80;

    visible.forEach((gesture, index) => {
      const x = visible.length === 1 ? 450 : left + (index / (visible.length - 1)) * width;
      const lane = lanes.indexOf(gesture.kind);
      const jitter = ((index % 3) - 1) * 8;
      positions.set(gesture.id, { x, y: laneTop + lane * laneGap + jitter });
    });

    visible.forEach((gesture) => {
      if (!gesture.responseTo || !visibleIds.has(gesture.responseTo)) return;
      const from = positions.get(gesture.responseTo);
      const to = positions.get(gesture.id);
      const bend = Math.max(30, Math.abs(to.x - from.x) * 0.42);
      const path = svgElement("path", {
        class: "constellation-edge",
        d: `M ${from.x} ${from.y} C ${from.x + bend} ${from.y}, ${to.x - bend} ${to.y}, ${to.x} ${to.y}`,
      });
      elements.constellationEdges.appendChild(path);
    });

    visible.forEach((gesture, index) => {
      const position = positions.get(gesture.id);
      const group = svgElement("g", {
        class: "constellation-node",
        tabindex: "0",
        role: "button",
        "aria-label": `${KINDS[gesture.kind].label}: ${gesture.text}`,
        transform: `translate(${position.x} ${position.y})`,
        style: `--node-color:${KINDS[gesture.kind].color}`,
        "data-id": gesture.id,
      });
      const title = svgElement("title");
      title.textContent = gesture.text;
      group.appendChild(title);
      group.appendChild(svgElement("circle", { r: gesture.id === selectedId ? "9" : "6" }));
      if (visible.length <= 22 || index === visible.length - 1) {
        const label = svgElement("text", { x: "11", y: "3" });
        label.textContent = truncate(gesture.text, 25);
        group.appendChild(label);
      }
      elements.constellationNodes.appendChild(group);
    });

    lanes.forEach((kindName) => {
      const legendItem = makeElement("span", "", KINDS[kindName].label);
      legendItem.style.setProperty("--legend-color", KINDS[kindName].color);
      elements.constellationLegend.appendChild(legendItem);
    });
  }

  function renderReceipts() {
    elements.receiptList.replaceChildren();
    const verified = verifyReceiptChain(state);
    elements.chainState.textContent = verified ? "Chain intact" : "Chain interrupted";
    elements.chainState.classList.toggle("is-broken", !verified);

    [...state.receipts].reverse().forEach((receipt) => {
      const item = makeElement("li", "receipt-item");
      item.appendChild(makeElement("span", "receipt-sequence", `#${String(receipt.seq).padStart(3, "0")}`));
      const body = makeElement("div", "");
      body.appendChild(makeElement("span", "receipt-action", receipt.action));
      body.appendChild(makeElement("span", "receipt-detail", receipt.detail));
      item.appendChild(body);
      const proof = makeElement("div", "receipt-proof");
      proof.appendChild(makeElement("code", "", receipt.hash));
      const time = makeElement("time", "", formatDate(receipt.at));
      time.dateTime = receipt.at;
      proof.appendChild(time);
      item.appendChild(proof);
      elements.receiptList.appendChild(item);
    });
  }

  function verdictColor(verdict) {
    if (verdict === "strains") return "#b85f42";
    if (verdict === "holds") return "#4e8061";
    return "#8b877e";
  }

  function renderInspector() {
    const gesture = selectedId ? findGesture(selectedId) : null;
    elements.inspectorIdle.hidden = Boolean(gesture);
    elements.inspectorContent.hidden = !gesture;
    if (!gesture) return;

    const kind = KINDS[gesture.kind];
    elements.inspectorKind.textContent = `${kind.glyph} ${kind.label}`;
    elements.inspectorKind.style.color = kind.color;
    elements.inspectorText.textContent = gesture.text;
    elements.inspectorTime.textContent = `${formatDate(gesture.createdAt)} · ${gesture.status}`;

    const parent = gesture.responseTo ? findGesture(gesture.responseTo) : null;
    elements.lineageSection.hidden = !parent;
    if (parent) {
      elements.lineageLink.textContent = `${KINDS[parent.kind].glyph} ${parent.text}`;
      elements.lineageLink.dataset.id = parent.id;
    }

    const rehearsal = latestRehearsalFor(gesture);
    const assessments = rehearsal?.meta.assessments || [];
    elements.tensionSection.hidden = !rehearsal;
    elements.tensionSummary.replaceChildren();
    if (rehearsal) {
      const summary = makeElement("div", "tension-summary");
      if (!assessments.length) {
        summary.appendChild(makeElement("p", "tension-summary-row", rehearsal.meta.notes || "A rehearsal was kept without active laws."));
      } else {
        assessments.forEach((assessment) => {
          const law = findGesture(assessment.lawId);
          if (!law) return;
          const row = makeElement(
            "div",
            "tension-summary-row",
            `${assessment.verdict}: ${truncate(law.text, 82)}`
          );
          row.style.setProperty("--row-color", verdictColor(assessment.verdict));
          summary.appendChild(row);
        });
        if (rehearsal.meta.notes) summary.appendChild(makeElement("p", "tension-summary-row", rehearsal.meta.notes));
      }
      elements.tensionSummary.appendChild(summary);
    }

    const receipt = lastReceiptFor(gesture.id);
    elements.inspectorReceipt.textContent = receipt ? `#${receipt.seq} · ${receipt.hash}` : "no receipt";
    elements.settleButton.textContent = gesture.status === "alive" ? "Settle this material" : "Return to living material";
  }

  function render() {
    renderHeader();
    renderMaterial();
    renderInspector();
    if (currentView === "constellation") renderConstellation();
    if (currentView === "receipts") renderReceipts();
  }

  function setSelectedKind(kind) {
    if (!KINDS[kind]) return;
    selectedKind = kind;
    elements.kindButtons.forEach((button) => {
      const active = button.dataset.kind === kind;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-checked", String(active));
    });
    elements.composerKindLabel.textContent = KINDS[kind].label;
    elements.composerText.placeholder = KINDS[kind].placeholder;
  }

  function selectGesture(id, options = {}) {
    const gesture = findGesture(id);
    if (!gesture) return;
    selectedId = id;
    renderMaterial();
    renderInspector();
    if (currentView === "constellation") renderConstellation();
    if (options.scroll) {
      const card = elements.materialList.querySelector(`[data-id="${window.CSS?.escape ? CSS.escape(id) : id}"]`);
      card?.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }

  function setReplyTarget(id) {
    const gesture = id ? findGesture(id) : null;
    replyToId = gesture?.id || null;
    elements.replyContext.hidden = !gesture;
    if (gesture) {
      elements.replyTarget.textContent = truncate(gesture.text, 44);
      elements.replyTarget.dataset.id = gesture.id;
    }
  }

  function addGesture(kind, text, responseTo = null, meta = {}) {
    const gesture = {
      id: uid("gesture"),
      kind,
      text: text.trim().slice(0, 600),
      responseTo: responseTo && findGesture(responseTo) ? responseTo : null,
      status: "alive",
      createdAt: nowIso(),
      meta,
    };
    state.gestures.push(gesture);
    appendReceipt(`place ${kind}`, gesture.id, gesture.text);
    persist();
    return gesture;
  }

  function handleComposerSubmit(event) {
    event.preventDefault();
    const text = elements.composerText.value.trim();
    if (!text) return;
    const gesture = addGesture(selectedKind, text, replyToId);
    elements.composerText.value = "";
    elements.characterCount.textContent = "0 / 600";
    setReplyTarget(null);
    selectedId = gesture.id;
    render();
    showToast(`${KINDS[gesture.kind].label} placed. Receipt #${state.receipts.length} kept.`);
  }

  function switchView(view) {
    if (!["material", "constellation", "receipts"].includes(view)) return;
    currentView = view;
    elements.viewTabs.forEach((tab) => {
      const active = tab.dataset.view === view;
      tab.classList.toggle("is-active", active);
      tab.setAttribute("aria-selected", String(active));
    });
    elements.materialView.hidden = view !== "material";
    elements.constellationView.hidden = view !== "constellation";
    elements.receiptView.hidden = view !== "receipts";
    elements.materialFilter.closest("label").hidden = view !== "material";
    if (view === "constellation") renderConstellation();
    if (view === "receipts") renderReceipts();
  }

  function openRehearsal(id) {
    const source = findGesture(id);
    if (!source) return;
    rehearsalSourceId = id;
    elements.rehearsalSource.textContent = source.text;
    elements.rehearsalNotes.value = "";
    elements.lawAssessments.replaceChildren();
    const laws = state.gestures.filter((gesture) => LAW_KINDS.has(gesture.kind) && gesture.status === "alive");

    if (!laws.length) {
      const empty = makeElement("p", "law-row", "No living laws are present. The rehearsal can still keep what surprised you.");
      elements.lawAssessments.appendChild(empty);
    }

    laws.forEach((law, index) => {
      const row = makeElement("div", "law-row");
      const lawText = makeElement("div", "law-text");
      lawText.appendChild(makeElement("span", "", KINDS[law.kind].label));
      lawText.appendChild(document.createTextNode(law.text));
      row.appendChild(lawText);
      const options = makeElement("div", "assessment-options");
      ["holds", "unknown", "strains"].forEach((verdict) => {
        const label = makeElement("label", `assessment-option ${verdict}`);
        const input = document.createElement("input");
        input.type = "radio";
        input.name = `law-${index}`;
        input.value = verdict;
        input.dataset.lawId = law.id;
        if (verdict === "unknown") input.checked = true;
        label.appendChild(input);
        label.appendChild(makeElement("span", "", verdict));
        options.appendChild(label);
      });
      row.appendChild(options);
      elements.lawAssessments.appendChild(row);
    });
    elements.rehearsalDialog.showModal();
  }

  function saveRehearsal(event) {
    event.preventDefault();
    if (event.submitter?.value === "cancel") {
      elements.rehearsalDialog.close();
      return;
    }
    const source = findGesture(rehearsalSourceId);
    if (!source) {
      elements.rehearsalDialog.close();
      return;
    }
    const assessments = [...elements.lawAssessments.querySelectorAll("input:checked")].map((input) => ({
      lawId: input.dataset.lawId,
      verdict: input.value,
    }));
    const notes = elements.rehearsalNotes.value.trim();
    const strains = assessments.filter((item) => item.verdict === "strains").length;
    const holds = assessments.filter((item) => item.verdict === "holds").length;
    const text = notes || `Pressure test: ${strains} tension${strains === 1 ? "" : "s"}, ${holds} law${holds === 1 ? "" : "s"} holding.`;
    const rehearsal = addGesture("rehearsal", text, source.id, {
      sourceId: source.id,
      assessments,
      notes,
    });
    source.meta.latestRehearsalId = rehearsal.id;
    appendReceipt(
      "rehearse move",
      source.id,
      `${strains} strained · ${holds} held · ${assessments.length - strains - holds} unknown`
    );
    persist();
    selectedId = source.id;
    elements.rehearsalDialog.close();
    render();
    showToast(strains ? `${strains} tension${strains === 1 ? "" : "s"} made visible.` : "The move was rehearsed; no tension was declared.");
  }

  function saveHandoff(event) {
    event.preventDefault();
    const nextMove = elements.handoffInput.value.trim();
    if (nextMove === state.nextMove) {
      showToast("That thread is already held.");
      return;
    }
    state.nextMove = nextMove.slice(0, 280);
    appendReceipt("leave handoff", state.worldId, state.nextMove || "The next hand was left an open surface.");
    persist();
    renderHeader();
    showToast("The next hand will find this thread.");
  }

  function toggleSettled() {
    const gesture = findGesture(selectedId);
    if (!gesture) return;
    gesture.status = gesture.status === "alive" ? "settled" : "alive";
    appendReceipt(
      gesture.status === "settled" ? "settle material" : "revive material",
      gesture.id,
      truncate(gesture.text, 180)
    );
    persist();
    render();
    showToast(gesture.status === "settled" ? "Material settled; its trail remains." : "Material returned to the living edge.");
  }

  function exportWorld() {
    const envelope = {
      format: "tendora-world",
      exportedAt: nowIso(),
      seal: checksum(JSON.stringify(state)),
      world: state,
    };
    const blob = new Blob([JSON.stringify(envelope, null, 2)], { type: "application/json" });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.href = url;
    link.download = `the-hand-remains-${dayKey(new Date())}.json`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 0);
    showToast("A portable world was made. Keep the JSON anywhere you trust.");
  }

  async function importWorld(file) {
    if (!file) return;
    try {
      const parsed = JSON.parse(await file.text());
      if (
        parsed?.format === "tendora-world" &&
        parsed.seal !== checksum(JSON.stringify(parsed.world))
      ) {
        throw new Error("The portable snapshot seal does not match its contents.");
      }
      const carried = sanitizeImportedWorld(parsed?.format === "tendora-world" ? parsed.world : parsed);
      state = carried;
      const today = dayKey(new Date());
      if (!state.visits.includes(today)) state.visits.push(today);
      appendReceipt("import snapshot", state.worldId, `Carried from ${file.name.slice(0, 160)}.`);
      selectedId = null;
      replyToId = null;
      persist();
      render();
      showToast("The carried world is intact and now held here.");
    } catch (error) {
      showToast(`Import refused: ${error.message}`);
    } finally {
      elements.importFile.value = "";
    }
  }

  function resetWorld(event) {
    event.preventDefault();
    if (event.submitter?.value === "cancel") {
      elements.newWorldDialog.close();
      return;
    }
    if (elements.confirmPhrase.value.trim().toLowerCase() !== "begin again") return;
    state = createFreshWorld();
    selectedId = null;
    replyToId = null;
    selectedKind = "question";
    elements.materialFilter.value = "alive";
    setSelectedKind("question");
    setReplyTarget(null);
    persist();
    elements.newWorldDialog.close();
    elements.confirmPhrase.value = "";
    elements.confirmNewWorld.disabled = true;
    switchView("material");
    render();
    showToast("A fresh surface holds the inherited laws and an open question.");
  }

  function bindEvents() {
    elements.kindPalette.addEventListener("click", (event) => {
      const button = event.target.closest(".kind-button");
      if (button) setSelectedKind(button.dataset.kind);
    });

    elements.composer.addEventListener("submit", handleComposerSubmit);
    elements.composerText.addEventListener("input", () => {
      elements.characterCount.textContent = `${elements.composerText.value.length} / 600`;
    });
    elements.composerText.addEventListener("keydown", (event) => {
      if ((event.metaKey || event.ctrlKey) && event.key === "Enter") {
        elements.composer.requestSubmit();
      }
    });

    elements.materialList.addEventListener("click", (event) => {
      const button = event.target.closest("[data-select]");
      if (button) selectGesture(button.dataset.select);
    });
    elements.materialFilter.addEventListener("change", renderMaterial);

    elements.viewTabs.forEach((tab) => {
      tab.addEventListener("click", () => switchView(tab.dataset.view));
    });

    elements.constellationNodes.addEventListener("click", (event) => {
      const node = event.target.closest("[data-id]");
      if (!node) return;
      switchView("material");
      selectGesture(node.dataset.id, { scroll: true });
    });
    elements.constellationNodes.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      const node = event.target.closest("[data-id]");
      if (!node) return;
      event.preventDefault();
      switchView("material");
      selectGesture(node.dataset.id, { scroll: true });
    });

    elements.closeInspector.addEventListener("click", () => {
      selectedId = null;
      renderMaterial();
      renderInspector();
    });
    elements.lineageLink.addEventListener("click", () => selectGesture(elements.lineageLink.dataset.id, { scroll: true }));
    elements.threadButton.addEventListener("click", () => {
      const gesture = findGesture(selectedId);
      if (!gesture) return;
      setReplyTarget(gesture.id);
      setSelectedKind("question");
      elements.composerText.focus();
      elements.composer.scrollIntoView({ behavior: "smooth", block: "center" });
    });
    elements.rehearseButton.addEventListener("click", () => openRehearsal(selectedId));
    elements.settleButton.addEventListener("click", toggleSettled);
    elements.clearReply.addEventListener("click", () => setReplyTarget(null));
    elements.replyTarget.addEventListener("click", () => selectGesture(elements.replyTarget.dataset.id, { scroll: true }));

    elements.handoffForm.addEventListener("submit", saveHandoff);
    elements.editHandoffButton.addEventListener("click", () => {
      elements.handoffInput.focus();
      elements.handoffInput.select();
      elements.handoffInput.scrollIntoView({ behavior: "smooth", block: "center" });
    });

    elements.rehearsalForm.addEventListener("submit", saveRehearsal);
    elements.exportButton.addEventListener("click", exportWorld);
    elements.importButton.addEventListener("click", () => elements.importFile.click());
    elements.importFile.addEventListener("change", () => importWorld(elements.importFile.files?.[0]));

    elements.newWorldButton.addEventListener("click", () => elements.newWorldDialog.showModal());
    elements.confirmPhrase.addEventListener("input", () => {
      elements.confirmNewWorld.disabled = elements.confirmPhrase.value.trim().toLowerCase() !== "begin again";
    });
    elements.newWorldForm.addEventListener("submit", resetWorld);
    elements.newWorldDialog.addEventListener("close", () => {
      elements.confirmPhrase.value = "";
      elements.confirmNewWorld.disabled = true;
    });
  }

  function registerOfflineMaterial() {
    if ("serviceWorker" in navigator && /^https?:$/.test(window.location.protocol)) {
      navigator.serviceWorker.register("./sw.js").catch(() => {
        // The static workbench remains fully usable even when installation is unavailable.
      });
    }
  }

  function init() {
    cacheElements();
    state = loadState();
    noteVisit();
    bindEvents();
    setSelectedKind(selectedKind);
    render();
    persist();
    registerOfflineMaterial();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
})();

:root {
  --paper: #e9e3d7;
  --paper-deep: #dcd3c3;
  --paper-light: #f5f0e7;
  --ink: #17221d;
  --forest: #24382f;
  --forest-soft: #52655b;
  --muted: #6f746d;
  --hairline: rgba(23, 34, 29, 0.18);
  --hairline-dark: rgba(23, 34, 29, 0.34);
  --clay: #b85f42;
  --clay-soft: #d88967;
  --ochre: #b08a3d;
  --blue: #557888;
  --plum: #71596e;
  --radius: 2px;
  --serif: Iowan Old Style, Baskerville, "Times New Roman", serif;
  --sans: Avenir Next, Avenir, Futura, "Century Gothic", sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --shadow: 0 18px 45px rgba(48, 40, 27, 0.09);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  min-width: 320px;
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
}

button,
textarea,
select,
input {
  color: inherit;
  font: inherit;
}

button,
select {
  cursor: pointer;
}

button {
  border: 0;
}

textarea {
  resize: vertical;
}

::selection {
  background: var(--clay);
  color: white;
}

:focus-visible {
  outline: 2px solid var(--clay);
  outline-offset: 3px;
}

.paper-noise {
  position: fixed;
  z-index: 10;
  inset: 0;
  pointer-events: none;
  opacity: 0.22;
  background-image:
    repeating-radial-gradient(circle at 18% 32%, transparent 0, rgba(31, 40, 31, 0.13) 0.55px, transparent 0.8px, transparent 4px),
    repeating-radial-gradient(circle at 83% 61%, transparent 0, rgba(255, 255, 255, 0.8) 0.6px, transparent 0.9px, transparent 5px);
  background-size: 7px 9px, 11px 13px;
  mix-blend-mode: multiply;
}

.skip-link {
  position: fixed;
  z-index: 100;
  top: 12px;
  left: 12px;
  padding: 10px 14px;
  background: var(--ink);
  color: white;
  transform: translateY(-160%);
}

.skip-link:focus {
  transform: translateY(0);
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.eyebrow {
  margin: 0 0 8px;
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.17em;
  line-height: 1.2;
  text-transform: uppercase;
}

.site-header {
  position: relative;
  z-index: 11;
  display: flex;
  height: 78px;
  align-items: center;
  justify-content: space-between;
  padding: 0 clamp(20px, 3vw, 54px);
  border-bottom: 1px solid var(--hairline);
}

.identity {
  display: flex;
  align-items: center;
  gap: 13px;
  color: inherit;
  text-decoration: none;
}

.identity strong,
.identity small {
  display: block;
}

.identity strong {
  font-family: var(--serif);
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.identity small {
  color: var(--muted);
  font-size: 0.63rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.handmark {
  width: 34px;
  height: 34px;
  overflow: visible;
  fill: none;
  stroke: var(--forest);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.25;
}

.handmark circle {
  fill: var(--clay);
  stroke: none;
}

.save-state {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.save-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4e8061;
  box-shadow: 0 0 0 4px rgba(78, 128, 97, 0.12);
  transition: background 180ms ease;
}

.save-state.is-saving .save-dot {
  background: var(--ochre);
}

.world-shell {
  position: relative;
  z-index: 1;
  display: grid;
  max-width: 1680px;
  min-height: calc(100vh - 78px);
  margin: 0 auto;
  grid-template-columns: 220px minmax(520px, 1fr) 330px;
}

.tool-rail,
.inspector {
  padding: 42px 26px;
}

.tool-rail {
  border-right: 1px solid var(--hairline);
}

.kind-palette {
  display: grid;
  gap: 5px;
  margin-top: 22px;
}

.kind-button {
  --kind-color: var(--clay);
  position: relative;
  display: grid;
  width: 100%;
  min-height: 58px;
  padding: 8px 7px;
  border-left: 2px solid transparent;
  background: transparent;
  grid-template-columns: 34px 1fr;
  align-items: center;
  text-align: left;
  transition: background 150ms ease, border-color 150ms ease, transform 150ms ease;
}

.kind-button[data-kind="constraint"] { --kind-color: var(--ochre); }
.kind-button[data-kind="invariant"] { --kind-color: var(--forest-soft); }
.kind-button[data-kind="boundary"] { --kind-color: var(--plum); }
.kind-button[data-kind="rehearsal"] { --kind-color: var(--blue); }
.kind-button[data-kind="witness"] { --kind-color: #74736a; }

.kind-button:hover {
  background: rgba(255, 255, 255, 0.3);
  transform: translateX(2px);
}

.kind-button.is-active {
  border-color: var(--kind-color);
  background: rgba(255, 255, 255, 0.5);
}

.kind-glyph {
  color: var(--kind-color);
  font-family: var(--serif);
  font-size: 1.2rem;
  text-align: center;
}

.kind-button strong,
.kind-button small {
  display: block;
}

.kind-button strong {
  font-size: 0.78rem;
}

.kind-button small {
  margin-top: 1px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 0.72rem;
  font-style: italic;
}

.rail-quote {
  margin: 64px 0 0;
  padding-left: 12px;
  border-left: 1px solid var(--clay-soft);
  color: var(--forest-soft);
  font-family: var(--serif);
  font-size: 0.9rem;
  font-style: italic;
}

.bench {
  min-width: 0;
  padding: 58px clamp(30px, 5vw, 82px) 100px;
}

.bench-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 38px;
}

.bench-heading h1 {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(2.5rem, 4.5vw, 5rem);
  font-weight: 400;
  letter-spacing: -0.045em;
  line-height: 0.94;
}

.bench-heading h1 em {
  color: var(--clay);
  font-weight: 400;
}

.continuity-count {
  min-width: 72px;
  padding: 9px 12px;
  border-top: 1px solid var(--hairline-dark);
  text-align: right;
}

.continuity-count span,
.continuity-count small {
  display: block;
}

.continuity-count span {
  font-family: var(--serif);
  font-size: 1.55rem;
  line-height: 1;
}

.continuity-count small {
  color: var(--muted);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.handoff {
  display: grid;
  margin-bottom: 18px;
  padding: 18px 20px;
  border: 1px solid rgba(184, 95, 66, 0.28);
  background: rgba(245, 240, 231, 0.5);
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  gap: 12px;
}

.handoff-symbol {
  color: var(--clay);
  font-family: var(--serif);
  font-size: 1.3rem;
}

.handoff .eyebrow {
  margin-bottom: 3px;
}

.handoff-text {
  margin: 0;
  font-family: var(--serif);
  font-size: 0.98rem;
  font-style: italic;
}

.text-button {
  padding: 2px 1px;
  border-bottom: 1px solid currentColor;
  background: transparent;
  color: var(--forest-soft);
  font-size: 0.69rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.text-button:hover {
  color: var(--clay);
}

.composer {
  position: relative;
  padding: 20px 22px 18px;
  border: 1px solid var(--hairline-dark);
  background: rgba(245, 240, 231, 0.78);
  box-shadow: var(--shadow);
}

.composer::before,
.composer::after {
  position: absolute;
  width: 14px;
  height: 14px;
  border-color: var(--clay);
  content: "";
}

.composer::before {
  top: -1px;
  left: -1px;
  border-top: 2px solid var(--clay);
  border-left: 2px solid var(--clay);
}

.composer::after {
  right: -1px;
  bottom: -1px;
  border-right: 2px solid var(--clay);
  border-bottom: 2px solid var(--clay);
}

.composer-meta {
  display: flex;
  min-height: 24px;
  align-items: center;
  justify-content: space-between;
  color: var(--clay);
  font-size: 0.67rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.reply-context {
  color: var(--muted);
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: none;
}

.reply-context button {
  padding: 0;
  background: transparent;
  color: var(--forest);
  text-decoration: underline;
  text-decoration-color: var(--hairline-dark);
  text-underline-offset: 3px;
}

.reply-context .clear-reply {
  margin-left: 6px;
  color: var(--clay);
  font-size: 1rem;
  text-decoration: none;
}

.composer textarea {
  display: block;
  width: 100%;
  min-height: 116px;
  margin: 9px 0 11px;
  padding: 3px 0;
  border: 0;
  background: transparent;
  font-family: var(--serif);
  font-size: clamp(1.25rem, 2.1vw, 1.8rem);
  line-height: 1.28;
}

.composer textarea:focus {
  outline: none;
}

.composer textarea::placeholder {
  color: #9a958b;
  font-style: italic;
}

.composer-actions {
  display: flex;
  min-height: 38px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.composer-actions > span {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.62rem;
}

.primary-button,
.secondary-button {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  justify-content: center;
  gap: 24px;
  padding: 9px 14px;
  font-size: 0.67rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: background 150ms ease, color 150ms ease, transform 150ms ease;
}

.primary-button {
  background: var(--forest);
  color: var(--paper-light);
}

.primary-button:hover {
  background: var(--clay);
  transform: translateY(-1px);
}

.primary-button:disabled {
  cursor: not-allowed;
  opacity: 0.38;
  transform: none;
}

.secondary-button {
  border: 1px solid var(--hairline-dark);
  background: transparent;
  color: var(--forest);
}

.secondary-button:hover {
  border-color: var(--forest);
  background: rgba(255, 255, 255, 0.38);
}

.view-bar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  margin-top: 52px;
  border-bottom: 1px solid var(--hairline-dark);
}

.view-tabs {
  display: flex;
  gap: 26px;
}

.view-tab {
  position: relative;
  padding: 0 0 13px;
  background: transparent;
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.view-tab::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  background: var(--clay);
  content: "";
  transform: scaleX(0);
  transition: transform 160ms ease;
}

.view-tab.is-active {
  color: var(--ink);
}

.view-tab.is-active::after {
  transform: scaleX(1);
}

.view-tab span {
  display: inline-grid;
  min-width: 19px;
  height: 19px;
  margin-left: 4px;
  border: 1px solid var(--hairline);
  border-radius: 50%;
  place-items: center;
  font-size: 0.56rem;
}

.filter-control select {
  padding: 7px 24px 8px 4px;
  border: 0;
  background: transparent;
  color: var(--muted);
  font-size: 0.68rem;
}

.view-panel {
  padding-top: 4px;
}

.material-list {
  display: grid;
}

.material-card {
  --kind-color: var(--clay);
  position: relative;
  display: grid;
  min-width: 0;
  padding: 21px 2px;
  border-bottom: 1px solid var(--hairline);
  grid-template-columns: 48px minmax(0, 1fr) auto;
  gap: 16px;
  animation: material-arrives 320ms ease both;
}

.material-card[data-kind="constraint"] { --kind-color: var(--ochre); }
.material-card[data-kind="invariant"] { --kind-color: var(--forest-soft); }
.material-card[data-kind="boundary"] { --kind-color: var(--plum); }
.material-card[data-kind="rehearsal"] { --kind-color: var(--blue); }
.material-card[data-kind="witness"] { --kind-color: #74736a; }

.material-card:hover {
  background: rgba(255, 255, 255, 0.19);
}

.material-card.is-selected::before {
  position: absolute;
  top: 15px;
  bottom: 15px;
  left: -12px;
  width: 2px;
  background: var(--kind-color);
  content: "";
}

.material-card.is-settled {
  opacity: 0.56;
}

.material-index {
  padding-top: 4px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.62rem;
}

.material-main {
  min-width: 0;
  padding: 0;
  background: transparent;
  text-align: left;
}

.material-type {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 5px;
  color: var(--kind-color);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.material-text {
  display: block;
  max-width: 720px;
  overflow-wrap: anywhere;
  font-family: var(--serif);
  font-size: 1.15rem;
  line-height: 1.35;
}

.material-lineage {
  display: block;
  max-width: 520px;
  margin-top: 7px;
  overflow: hidden;
  color: var(--muted);
  font-size: 0.68rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.material-meta {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.6rem;
  white-space: nowrap;
}

.tension-mark {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--clay);
  font-family: var(--sans);
  font-weight: 700;
}

.tension-mark::before {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--clay);
  content: "";
}

.empty-state {
  padding: 80px 20px;
  color: var(--muted);
  text-align: center;
}

.empty-state > span {
  color: var(--clay-soft);
  font-family: var(--serif);
  font-size: 2rem;
}

.empty-state p {
  max-width: 330px;
  margin: 12px auto;
  font-family: var(--serif);
  font-style: italic;
}

.constellation-view {
  padding-top: 26px;
}

.constellation-copy {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 20px;
}

.constellation-copy p:last-child {
  max-width: 420px;
  margin: 0;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 0.9rem;
  font-style: italic;
  text-align: right;
}

.constellation-frame {
  margin-top: 18px;
  border: 1px solid var(--hairline);
  background:
    linear-gradient(rgba(23, 34, 29, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(23, 34, 29, 0.035) 1px, transparent 1px),
    rgba(245, 240, 231, 0.44);
  background-size: 34px 34px;
}

.constellation-frame svg {
  display: block;
  width: 100%;
  min-height: 340px;
}

.constellation-edge {
  fill: none;
  stroke: rgba(23, 34, 29, 0.25);
  stroke-dasharray: 3 6;
  stroke-width: 1;
}

.constellation-node {
  cursor: pointer;
}

.constellation-node circle {
  fill: var(--paper-light);
  stroke: var(--node-color, var(--clay));
  stroke-width: 2;
  transition: r 150ms ease, fill 150ms ease;
}

.constellation-node:hover circle,
.constellation-node:focus circle {
  r: 10px;
  fill: var(--node-color, var(--clay));
}

.constellation-node text {
  fill: var(--ink);
  font-family: var(--sans);
  font-size: 9px;
}

.constellation-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  margin-top: 14px;
  color: var(--muted);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.constellation-legend span::before {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 6px;
  border-radius: 50%;
  background: var(--legend-color);
  content: "";
}

.receipt-view {
  padding-top: 29px;
}

.receipt-intro {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}

.receipt-intro h2 {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.6rem;
  font-weight: 400;
}

.chain-state {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 9px;
  border: 1px solid var(--hairline);
  color: var(--forest-soft);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.chain-state::before {
  color: #4e8061;
  content: "●";
}

.chain-state.is-broken {
  color: var(--clay);
}

.chain-state.is-broken::before {
  color: var(--clay);
}

.receipt-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.receipt-item {
  display: grid;
  padding: 15px 0;
  border-top: 1px solid var(--hairline);
  grid-template-columns: 42px 1fr auto;
  gap: 12px;
}

.receipt-sequence {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.6rem;
}

.receipt-action {
  display: block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.receipt-detail {
  display: block;
  margin-top: 3px;
  overflow-wrap: anywhere;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 0.85rem;
  font-style: italic;
}

.receipt-proof {
  text-align: right;
}

.receipt-proof code,
.receipt-proof time {
  display: block;
}

.receipt-proof code {
  color: var(--clay);
  font-family: var(--mono);
  font-size: 0.61rem;
}

.receipt-proof time {
  margin-top: 3px;
  color: var(--muted);
  font-size: 0.58rem;
}

.inspector {
  position: sticky;
  top: 0;
  align-self: start;
  min-height: calc(100vh - 78px);
  border-left: 1px solid var(--hairline);
  background: rgba(220, 211, 195, 0.36);
}

.inspector-idle {
  min-height: 300px;
  padding: 55px 6px 40px;
}

.inspector-mark {
  display: block;
  margin-bottom: 24px;
  color: var(--clay-soft);
  font-size: 1.3rem;
}

.inspector-idle h2,
.continuation-panel h2,
.inspector-content h2 {
  font-family: var(--serif);
  font-weight: 400;
}

.inspector-idle h2 {
  margin: 0 0 12px;
  font-size: 1.55rem;
  line-height: 1.15;
}

.inspector-idle > p:last-child {
  color: var(--muted);
  font-family: var(--serif);
  font-size: 0.88rem;
  font-style: italic;
}

.inspector-content {
  min-height: 440px;
  padding: 12px 0 35px;
}

.inspector-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 22px;
}

.kind-chip {
  color: var(--clay);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.icon-button {
  display: inline-grid;
  width: 31px;
  height: 31px;
  border: 1px solid var(--hairline);
  border-radius: 50%;
  background: transparent;
  place-items: center;
  font-family: var(--serif);
  font-size: 1.1rem;
}

.icon-button:hover {
  border-color: var(--clay);
  color: var(--clay);
}

.inspector-content h2 {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: 1.45rem;
  line-height: 1.2;
}

.inspector-time {
  margin: 9px 0 24px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.61rem;
}

.inspector-section {
  padding: 17px 0;
  border-top: 1px solid var(--hairline);
}

.lineage-link {
  padding: 0;
  background: transparent;
  color: var(--forest-soft);
  font-family: var(--serif);
  font-size: 0.88rem;
  font-style: italic;
  text-align: left;
}

.lineage-link:hover {
  color: var(--clay);
}

.tension-summary {
  display: grid;
  gap: 8px;
}

.tension-summary-row {
  display: grid;
  grid-template-columns: 9px 1fr;
  gap: 7px;
  color: var(--muted);
  font-size: 0.69rem;
}

.tension-summary-row::before {
  margin-top: 4px;
  color: var(--row-color, var(--muted));
  content: "●";
  font-size: 0.47rem;
}

.receipt-stub code {
  color: var(--clay);
  font-family: var(--mono);
  font-size: 0.66rem;
}

.inspector-actions {
  display: grid;
  gap: 9px;
  padding-top: 19px;
  border-top: 1px solid var(--hairline);
}

.inspector-actions .quiet {
  width: max-content;
  margin: 8px auto 0;
  border-bottom-color: transparent;
  color: var(--muted);
}

.continuation-panel,
.portability-panel {
  padding-top: 28px;
  border-top: 1px solid var(--hairline-dark);
}

.continuation-panel h2 {
  margin: 0 0 13px;
  font-size: 1.2rem;
  line-height: 1.2;
}

.continuation-panel textarea {
  width: 100%;
  padding: 10px;
  border: 1px solid var(--hairline);
  background: rgba(245, 240, 231, 0.48);
  font-family: var(--serif);
  font-size: 0.82rem;
}

.continuation-panel .secondary-button {
  width: 100%;
  margin-top: 7px;
}

.portability-panel {
  margin-top: 28px;
}

.data-actions {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
}

.data-actions .danger {
  color: #95513e;
}

dialog {
  width: min(680px, calc(100vw - 32px));
  max-height: min(820px, calc(100vh - 32px));
  padding: 0;
  border: 1px solid var(--hairline-dark);
  border-radius: 0;
  background: var(--paper-light);
  box-shadow: 0 40px 100px rgba(23, 34, 29, 0.28);
  color: var(--ink);
}

dialog::backdrop {
  background: rgba(23, 34, 29, 0.64);
  backdrop-filter: blur(3px);
}

dialog form {
  padding: clamp(24px, 5vw, 48px);
}

.dialog-heading {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 20px;
}

.dialog-heading h2,
.confirm-dialog h2 {
  margin: 0;
  font-family: var(--serif);
  font-size: 2rem;
  font-weight: 400;
  line-height: 1.08;
}

.rehearsal-dialog blockquote {
  margin: 28px 0;
  padding: 15px 18px;
  border-left: 2px solid var(--clay);
  background: var(--paper);
  font-family: var(--serif);
  font-size: 1.04rem;
  font-style: italic;
}

.law-assessments {
  display: grid;
  gap: 1px;
  background: var(--hairline);
  border: 1px solid var(--hairline);
}

.law-row {
  padding: 14px 15px;
  background: var(--paper-light);
}

.law-text {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 11px;
  font-family: var(--serif);
  font-size: 0.88rem;
}

.law-text span {
  color: var(--muted);
  font-family: var(--sans);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.assessment-options {
  display: flex;
  gap: 6px;
}

.assessment-option {
  position: relative;
}

.assessment-option input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.assessment-option span {
  display: block;
  padding: 5px 9px;
  border: 1px solid var(--hairline);
  color: var(--muted);
  font-size: 0.59rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.assessment-option input:focus-visible + span {
  outline: 2px solid var(--clay);
  outline-offset: 2px;
}

.assessment-option input:checked + span {
  border-color: var(--forest);
  background: var(--forest);
  color: white;
}

.assessment-option.strains input:checked + span {
  border-color: var(--clay);
  background: var(--clay);
}

.notes-field {
  display: grid;
  gap: 7px;
  margin-top: 25px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.notes-field textarea,
.confirm-dialog input {
  width: 100%;
  padding: 11px;
  border: 1px solid var(--hairline-dark);
  background: var(--paper);
  font-family: var(--serif);
  font-size: 0.9rem;
  text-transform: none;
}

.dialog-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 22px;
  margin-top: 27px;
}

.confirm-dialog p:not(.eyebrow) {
  color: var(--muted);
  font-family: var(--serif);
}

.confirm-dialog label {
  display: block;
  margin: 22px 0 7px;
  font-size: 0.72rem;
}

.destructive {
  background: #8c4937;
}

.toast {
  position: fixed;
  z-index: 80;
  right: 24px;
  bottom: 24px;
  max-width: min(380px, calc(100vw - 48px));
  padding: 12px 15px;
  background: var(--forest);
  color: var(--paper-light);
  font-size: 0.72rem;
  opacity: 0;
  pointer-events: none;
  transform: translateY(12px);
  transition: opacity 180ms ease, transform 180ms ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.noscript {
  position: fixed;
  z-index: 100;
  right: 20px;
  bottom: 20px;
  left: 20px;
  padding: 15px;
  background: var(--clay);
  color: white;
  text-align: center;
}

@keyframes material-arrives {
  from { opacity: 0; transform: translateY(7px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 1220px) {
  .world-shell {
    grid-template-columns: 170px minmax(500px, 1fr) 285px;
  }

  .tool-rail,
  .inspector {
    padding-right: 18px;
    padding-left: 18px;
  }

  .bench {
    padding-right: 40px;
    padding-left: 40px;
  }

  .kind-button {
    grid-template-columns: 26px 1fr;
  }
}

@media (max-width: 1020px) {
  .world-shell {
    grid-template-columns: 1fr 285px;
  }

  .tool-rail {
    display: block;
    padding: 20px 30px;
    border-right: 0;
    border-bottom: 1px solid var(--hairline);
    grid-column: 1 / -1;
  }

  .tool-rail > .eyebrow,
  .rail-quote {
    display: none;
  }

  .kind-palette {
    display: flex;
    overflow-x: auto;
    margin: 0;
    gap: 2px;
  }

  .kind-button {
    min-width: 132px;
    min-height: 49px;
  }

  .kind-button small {
    display: none;
  }

  .bench {
    padding-top: 45px;
  }
}

@media (max-width: 760px) {
  .site-header {
    height: 66px;
    padding: 0 18px;
  }

  .identity small {
    display: none;
  }

  .world-shell {
    display: block;
    min-height: calc(100vh - 66px);
  }

  .tool-rail {
    padding: 12px;
  }

  .kind-button {
    min-width: 54px;
    width: auto;
    padding: 7px;
    grid-template-columns: 1fr;
    text-align: center;
  }

  .kind-button span:last-child {
    display: none;
  }

  .bench {
    padding: 38px 18px 60px;
  }

  .bench-heading {
    align-items: start;
    margin-bottom: 28px;
  }

  .bench-heading h1 {
    font-size: clamp(2.55rem, 13vw, 4rem);
  }

  .handoff {
    grid-template-columns: 24px 1fr;
  }

  .handoff .text-button {
    grid-column: 2;
    justify-self: start;
  }

  .composer {
    padding: 16px;
  }

  .composer textarea {
    min-height: 105px;
  }

  .composer-actions {
    align-items: end;
  }

  .view-bar {
    align-items: stretch;
    flex-direction: column-reverse;
  }

  .view-tabs {
    width: 100%;
    justify-content: space-between;
    gap: 10px;
  }

  .filter-control select {
    float: right;
  }

  .material-card {
    grid-template-columns: 30px minmax(0, 1fr);
    gap: 8px;
  }

  .material-meta {
    padding: 7px 0 0 38px;
    grid-column: 1 / -1;
  }

  .constellation-copy {
    display: block;
  }

  .constellation-copy p:last-child {
    margin-top: 10px;
    text-align: left;
  }

  .receipt-item {
    grid-template-columns: 30px 1fr;
  }

  .receipt-proof {
    grid-column: 2;
    text-align: left;
  }

  .receipt-proof code,
  .receipt-proof time {
    display: inline;
    margin-right: 8px;
  }

  .inspector {
    position: static;
    min-height: 0;
    padding: 38px 18px;
    border-top: 1px solid var(--hairline-dark);
    border-left: 0;
  }

  .inspector-idle {
    min-height: 0;
    padding: 12px 0 28px;
  }

  .dialog-heading h2,
  .confirm-dialog h2 {
    font-size: 1.6rem;
  }

  .assessment-options {
    flex-wrap: wrap;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@media print {
  .site-header,
  .tool-rail,
  .composer,
  .view-bar,
  .inspector,
  .paper-noise {
    display: none !important;
  }

  body {
    background: white;
  }

  .world-shell {
    display: block;
  }

  .bench {
    padding: 20px;
  }

  .material-card {
    break-inside: avoid;
  }
}

const CACHE = "the-hand-remains-v2";
const MATERIAL = [
  "./",
  "./index.html",
  "./styles.css",
  "./app.js",
  "./manifest.webmanifest",
  "./icon.svg",
];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(MATERIAL)));
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key)))
    )
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;
  event.respondWith(
    caches.match(event.request).then((cached) =>
      cached || fetch(event.request).then((response) => {
        const copy = response.clone();
        caches.open(CACHE).then((cache) => cache.put(event.request, copy));
        return response;
      })
    )
  );
});
